/** Traducao de codigo recebido do site para a opcao cadastrada no sistema. */
public final class Catalogo {

    private Catalogo() {
    }

    public static <E extends Enum<E>> E exigir(Class<E> opcoes, String codigo, ErroCheckout erro) {
